def get_dpr_app_models():
    """Dynamically locates db, SurveyTask, AppConfig, and format_clean_description from your main DPR app.py."""
    for mod_name in ("app", "__main__"):
        mod = sys.modules.get(mod_name)
        if mod and hasattr(mod, "SurveyTask"):
            return (
                getattr(mod, "db", None),
                getattr(mod, "SurveyTask", None),
                getattr(mod, "AppConfig", None),
                getattr(mod, "format_clean_description", None),
            )
    try:
        import app as dpr_app
        return (
            getattr(dpr_app, "db", None),
            getattr(dpr_app, "SurveyTask", None),
            getattr(dpr_app, "AppConfig", None),
            getattr(dpr_app, "format_clean_description", None),
        )
    except Exception:
        return None, None, None, None


def load_state_from_appconfig(config_id: str):
    db, _, AppConfig, _ = get_dpr_app_models()
    if db and AppConfig:
        try:
            rec = AppConfig.query.filter_by(id=config_id).first()
            if rec and rec.schema_data:
                return json.loads(rec.schema_data)
        except Exception:
            pass
    return None


def save_state_to_appconfig(config_id: str, data_obj: dict):
    db, _, AppConfig, _ = get_dpr_app_models()
    if db and AppConfig:
        try:
            rec = AppConfig.query.filter_by(id=config_id).first()
            if not rec:
                rec = AppConfig(id=config_id, schema_data=json.dumps(data_obj))
                db.session.add(rec)
            else:
                rec.schema_data = json.dumps(data_obj)
            db.session.commit()
        except Exception:
            try:
                db.session.rollback()
            except Exception:
                pass


