def extract_admin_tables_from_docx_file(docx_path: str) -> dict:
    if not os.path.exists(docx_path):
        return {}
    try:
        doc_obj = docx.Document(docx_path)
        out = {"personnel": [], "leave": [], "training": []}
        mapping = [("personnel", 1, 2), ("leave", 2, 2), ("training", 3, 1)]
        for key, t_idx, h_cnt in mapping:
            if t_idx >= len(doc_obj.tables):
                continue
            t = doc_obj.tables[t_idx]
            for r in t.rows[h_cnt:]:
                row_list = []
                for c in r.cells:
                    txt = "\n".join(p.text.strip() for p in c.paragraphs if p.text.strip())
                    has_hl = any(
                        run.font.highlight_color == WD_COLOR_INDEX.YELLOW
                        for p in c.paragraphs for run in p.runs
                    )
                    row_list.append({"text": txt, "highlight": has_hl})
                out[key].append(row_list)
        return out
    except Exception:
        return {}


def load_admin_tables() -> dict:
    db_saved = load_state_from_appconfig("wsr_admin_tables")
    if db_saved and db_saved.get("personnel"):
        return db_saved
    if os.path.exists(ADMIN_TABLES_PATH):
        try:
            with open(ADMIN_TABLES_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
                if data.get("personnel") and data.get("leave") and data.get("training"):
                    return data
        except Exception:
            pass
    extracted = extract_admin_tables_from_docx_file(TEMPLATE_PATH)
    if extracted.get("personnel"):
        save_admin_tables(extracted)
        return extracted
    return {}


def save_admin_tables(tables_data: dict) -> dict:
    try:
        with open(ADMIN_TABLES_PATH, "w", encoding="utf-8") as f:
            json.dump(tables_data, f, indent=2)
    except Exception:
        pass
    save_state_to_appconfig("wsr_admin_tables", tables_data)
    return tables_data


def update_docx_admin_table(table, header_rows_count: int, rows_data: list):
    if not rows_data:
        return
    existing_data_rows = len(table.rows) - header_rows_count
    target_data_rows = len(rows_data)

    while existing_data_rows < target_data_rows:
        template_tr = table.rows[-1]._tr
        new_tr = copy.deepcopy(template_tr)
        table._tbl.append(new_tr)
        existing_data_rows += 1

    while existing_data_rows > target_data_rows and len(table.rows) > header_rows_count:
        last_tr = table.rows[-1]._tr
        table._tbl.remove(last_tr)
        existing_data_rows -= 1

    for r_idx, row_cells in enumerate(rows_data):
        row = table.rows[header_rows_count + r_idx]
        for c_idx, cell_obj in enumerate(row_cells):
            if c_idx >= len(row.cells):
                break
            cell = row.cells[c_idx]
            txt = str(cell_obj.get("text", "") if isinstance(cell_obj, dict) else cell_obj)
            is_hl = bool(cell_obj.get("highlight", False)) if isinstance(cell_obj, dict) else False

            cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER
            while len(cell.paragraphs) > 1:
                p_elem = cell.paragraphs[-1]._element
                p_elem.getparent().remove(p_elem)

            lines = txt.split("\n")
            for l_i, line_str in enumerate(lines):
                p = cell.paragraphs[0] if l_i == 0 else cell.add_paragraph()
                if l_i == 0:
                    p.text = ""
                p.alignment = WD_ALIGN_PARAGRAPH.CENTER
                p.paragraph_format.space_before = Pt(1)
                p.paragraph_format.space_after = Pt(1)
                run = p.add_run(line_str)
                run.font.name = "Arial"
                run.font.size = Pt(8)
                run.bold = False
                if is_hl:
                    run.font.highlight_color = WD_COLOR_INDEX.YELLOW

    for h_idx in range(header_rows_count):
        for cell in table.rows[h_idx].cells:
            for p in cell.paragraphs:
                for run in p.runs:
                    run.font.name = "Arial"
                    run.font.size = Pt(8)
                    run.bold = True


def apply_admin_tables_to_doc(doc_obj, admin_tables: dict):
    if not admin_tables or len(doc_obj.tables) < 4:
        return
    if admin_tables.get("personnel"):
        update_docx_admin_table(doc_obj.tables[1], 2, admin_tables["personnel"])
    if admin_tables.get("leave"):
        update_docx_admin_table(doc_obj.tables[2], 2, admin_tables["leave"])
    if admin_tables.get("training"):
        update_docx_admin_table(doc_obj.tables[3], 1, admin_tables["training"])


