def load_ai_config() -> dict:
    cfg = {
        "provider": "gemini",
        "gemini_api_key": os.environ.get("GEMINI_API_KEY", ""),
        "gemini_model": "gemini-2.5-flash",
        "ollama_url": "http://127.0.0.1:11434/api/generate",
        "ollama_model": "llama3.1",
    }
    db_cfg = load_state_from_appconfig("wsr_ai_config")
    if db_cfg:
        cfg.update({k: v for k, v in db_cfg.items() if v is not None})
    if os.path.exists(AI_CONFIG_PATH):
        try:
            with open(AI_CONFIG_PATH, "r", encoding="utf-8") as f:
                saved = json.load(f)
                cfg.update({k: v for k, v in saved.items() if v is not None})
        except Exception:
            pass
    return cfg


def save_ai_config(new_cfg: dict):
    cfg = load_ai_config()
    cfg.update({k: v for k, v in new_cfg.items() if v is not None})
    try:
        with open(AI_CONFIG_PATH, "w", encoding="utf-8") as f:
            json.dump(cfg, f, indent=2)
    except Exception:
        pass
    save_state_to_appconfig("wsr_ai_config", cfg)
    return cfg


def parse_prev_wsr_raw_text(raw_text: str) -> dict:
    text_fixed = re.sub(r"([a-zA-Z])-\r?\n\s*([a-zA-Z])", r"\1-\2", raw_text)
    cleaned = re.sub(r"From No\.:\s*#\d+\s*\d*", "", text_fixed)
    cleaned = re.sub(r"MDC\s+DREDGING & MARINE[\s\S]*?20012\s*WSR\s*\d{4}\.\d{2}", "", cleaned)
    cleaned = re.sub(r"Weekly Survey Report[\s\S]*?20012\s*WSR\s*\d{4}\.\d{2}", "", cleaned)

    m_wk = re.search(r"WSR\s*(\d{4}\.\d{2})", raw_text)
    prev_week = m_wk.group(1) if m_wk else ""

    def extract_block(start_hdr, end_hdr):
        pattern = re.compile(rf"{start_hdr}\s*([\s\S]*?)\s*{end_hdr}", re.IGNORECASE)
        m = pattern.search(cleaned)
        if not m:
            return []
        block = m.group(1).strip()
        items = re.split(r"(?:^|\n)\s*(?:\d+[\.\)]\s+|\*\s+|-\s+)", block)
        out = []
        for it in items:
            single_line = " ".join(
                line.strip() for line in it.splitlines()
                if line.strip() and not line.strip().startswith("---")
            )
            if single_line:
                out.append(single_line)
        return out

    image_date_patterns = {
        "img_on_ahdd": r"Taichung AHDD Site:\s*\(([^)]+)\)",
        "img_on_tienli": r"Taichung Tienli Site:\s*\(([^)]+)\)",
        "img_on_b37": r"Taichung Berth 37 Site:\s*\(([^)]+)\)",
        "img_on_tunghsiao": r"Tunghsiao Temporary Platform AHDD Site:\s*\(([^)]+)\)",
        "img_nr_t1_float": r"Floatation Channel CH\s*[-–]265 to \+CH 180[\s\S]{0,80}?Monitoring Survey\s*\(([^)]+)\)",
        "img_nr_t1_main": r"CH 180 to CH 1340[\s\S]{0,80}?Monitoring Survey\s*\(([^)]+)\)",
        "img_nr_t8": r"Trench 8[\s\S]{0,80}?Monitoring Survey\s*\(([^)]+)\)",
        "img_nr_midline": r"Midline Tie-In[\s\S]{0,80}?Monitoring Survey\s*\(([^)]+)\)",
        "img_nr_dump_tc": r"Dumping area monitoring \(Taichung Nearshore\)[\s\S]{0,80}?Monitoring Survey\s*\(([^)]+)\)",
        "img_nr_dump_ts": r"Dumping area monitoring \(Tunghsiao Nearshore\)[\s\S]{0,80}?Monitoring Survey\s*\(([^)]+)\)",
        "img_off_matt_1": r"Crossings A 1,2 and B 1,2\s*\(([^)]+)\)",
        "img_off_matt_3": r"Crossings A 3 and B 3\s*\(([^)]+)\)",
        "img_off_fengmiao": r"Fengmiao OEC1 and OEC2\s*\(([^)]+)\)",
    }
    extracted_img_dates = {}
    for img_id, pat in image_date_patterns.items():
        m_dt = re.search(pat, raw_text, re.IGNORECASE)
        if m_dt:
            extracted_img_dates[img_id] = m_dt.group(1).strip()

    return {
        "prev_week": prev_week,
        "highlights": extract_block("Highlights", "Look ahead"),
        "look_ahead": extract_block("Look ahead", "Outstanding Tasks"),
        "outstanding_tasks": extract_block("Outstanding Tasks", "Hardware Movement and Status"),
        "hardware_status": extract_block("Hardware Movement and Status", "NMDC Hardware from Abu Dhabi"),
        "image_dates": extracted_img_dates,
    }


def extract_text_from_file(filepath: str) -> str:
    ext = os.path.splitext(filepath)[1].lower()
    if ext == ".docx":
        d = docx.Document(filepath)
        lines = []
        for s in d.sections:
            for ht in s.header.tables:
                for r in ht.rows:
                    lines.append(" ".join(c.text.strip() for c in r.cells if c.text.strip()))
        for p in d.paragraphs:
            if p.text.strip():
                lines.append(p.text.strip())
        return "\n".join(lines)
    elif ext == ".pdf":
        for mod_name in ("pypdf", "PyPDF2"):
            try:
                mod = __import__(mod_name)
                reader = mod.PdfReader(filepath)
                return "\n".join((page.extract_text() or "") for page in reader.pages)
            except Exception:
                pass
        try:
            import fitz
            doc_pdf = fitz.open(filepath)
            return "\n".join(page.get_text() for page in doc_pdf)
        except Exception:
            pass
    return ""


