def call_gemini_json(system_instruction: str, user_content: str, api_key: str, model_name: str = "gemini-2.5-flash") -> dict:
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model_name}:generateContent?key={api_key}"
    body = {
        "system_instruction": {"parts": [{"text": system_instruction}]},
        "contents": [{"role": "user", "parts": [{"text": user_content}]}],
        "generationConfig": {
            "temperature": 0.2,
            "responseMimeType": "application/json",
        },
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(body).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=35) as resp:
        resp_data = json.loads(resp.read().decode("utf-8"))
    text_out = resp_data["candidates"][0]["content"]["parts"][0]["text"]
    return json.loads(text_out)


def call_ollama_json(system_instruction: str, user_content: str, ollama_url: str, ollama_model: str) -> dict:
    prompt = f"{system_instruction}\n\n{user_content}"
    body = {
        "model": ollama_model,
        "prompt": prompt,
        "format": "json",
        "stream": False,
    }
    req = urllib.request.Request(
        ollama_url,
        data=json.dumps(body).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=45) as resp:
        resp_data = json.loads(resp.read().decode("utf-8"))
    return json.loads(resp_data["response"])


