# 4. WORD & PDF GENERATION ENGINE
# ==============================================================================
def insert_paragraph_after(paragraph: Paragraph, text: str = "", keep_with_next: bool = False, space_before_pt: float = 0, space_after_pt: float = 2) -> Paragraph:
    new_p = OxmlElement("w:p")
    paragraph._p.addnext(new_p)
    new_para = Paragraph(new_p, paragraph._parent)
    new_para.paragraph_format.keep_with_next = keep_with_next
    new_para.paragraph_format.keep_together = True
    new_para.paragraph_format.space_before = Pt(space_before_pt)
    new_para.paragraph_format.space_after = Pt(space_after_pt)
    if text:
        new_para.add_run(text)
    return new_para


def apply_font_and_format(run, is_bold: bool = False, is_highlight: bool = False, size_pt: float = 10):
    run.font.name = "Arial"
    run.font.size = Pt(size_pt)
    run.bold = is_bold
    if is_highlight:
        run.font.highlight_color = WD_COLOR_INDEX.BRIGHT_GREEN


def sanitize_task_text(text: str) -> str:
    text = re.sub(r"\|\s*Acknowledged\s*Started by.*", "", text, flags=re.IGNORECASE)
    replacements = {
        "Settlement Settlement": "Settlement",
        "Benchmark Benchmark": "Benchmark",
        "Internal Internal": "Internal",
        "Others Others": "Survey",
        "Survey Survey": "Survey",
        "Design Design": "Design",
        "TAichung": "Taichung",
        "Tungshiao and sites": "Tunghsiao and Taichung sites",
        "Tunghsiao and sites": "Tunghsiao and Taichung sites",
        "Tungshiao": "Tunghsiao",
        "Tungshioa": "Tunghsiao",
        "Tungxiao": "Tunghsiao",
        "Tonghsiao": "Tunghsiao",
        "sttlement": "settlement",
        "  ": " ",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return text.strip()


def parse_raw_daily_text(raw_text: str) -> list:
    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
    days = []
    current_day = None
    current_section = None
    current_vessel = None

    date_pattern = re.compile(
        r"^(\d{2}\.\d{2}\.\d{4})\s+(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)",
        re.IGNORECASE,
    )

    for line in lines:
        m = date_pattern.match(line)
        if m:
            if current_day:
                days.append(current_day)
            current_day = {
                "date_full": f"{m.group(1)} {m.group(2)}",
                "office_staff": "",
                "office_tasks": [],
                "onshore_staff": "",
                "onshore_tasks": [],
                "marine_staff": "",
                "marine_tasks": [],
                "vessels": [],
                "general_notes": [],
            }
            current_section = None
            current_vessel = None
            continue

        if not current_day:
            continue

        if line.startswith("Wuqi Office:"):
            current_day["office_staff"] = line.split(":", 1)[1].strip()
            current_section = "office"
            current_vessel = None
        elif line.startswith("Onshore-Land:"):
            current_day["onshore_staff"] = line.split(":", 1)[1].strip()
            current_section = "onshore"
            current_vessel = None
        elif line.startswith("Marine Offshore:"):
            current_day["marine_staff"] = line.split(":", 1)[1].strip()
            current_section = "marine"
            current_vessel = None
        elif "Hydro Survey" in line:
            if "(" in line and "Survey Boat:" in line:
                hdr = line.split("(")[0].strip()
                inner = line.split("(", 1)[1].rstrip(")")
                parts = inner.split("|")
                boat = parts[0].replace("Survey Boat:", "").strip() if len(parts) > 0 else ""
                surv = parts[1].replace("Surveyor:", "").strip() if len(parts) > 1 else ""
                current_vessel = {"header": hdr, "boat": boat, "surveyor": surv, "statuses": []}
            else:
                current_vessel = {"header": line, "boat": "", "surveyor": "", "statuses": []}
            current_day["vessels"].append(current_vessel)
            current_section = "vessel"
        elif current_section == "vessel" and current_vessel is not None:
            if line.startswith("Survey Boat:"):
                current_vessel["boat"] = line.split(":", 1)[1].strip()
            elif line.startswith("Surveyor:"):
                current_vessel["surveyor"] = line.split(":", 1)[1].strip()
            else:
                clean_st = sanitize_task_text(line.lstrip("-").lstrip(">").strip())
                if clean_st and clean_st not in current_vessel["statuses"]:
                    current_vessel["statuses"].append(clean_st)
        elif line.startswith("-"):
            clean_t = sanitize_task_text(line.lstrip("-").strip())
            if current_section == "office" and clean_t not in current_day["office_tasks"]:
                current_day["office_tasks"].append(clean_t)
            elif current_section == "onshore" and clean_t not in current_day["onshore_tasks"]:
                current_day["onshore_tasks"].append(clean_t)
            elif current_section == "marine" and clean_t not in current_day["marine_tasks"]:
                current_day["marine_tasks"].append(clean_t)
            elif current_section is None and clean_t not in current_day["general_notes"]:
                current_day["general_notes"].append(clean_t)
        else:
            clean_n = sanitize_task_text(line)
            if clean_n and clean_n not in current_day["general_notes"]:
                current_day["general_notes"].append(clean_n)

    if current_day:
        days.append(current_day)
    return days


def find_persistent_image(img_id: str):
    for ext in [".png", ".jpg", ".jpeg"]:
        candidate = os.path.join(PERSISTENT_IMAGE_DIR, f"{img_id}{ext}")
        if os.path.exists(candidate):
            return candidate
    return None


def insert_daily_logs(doc, payload):
    target_p = None
    for p in doc.paragraphs:
        if p.text.strip() == "Daily Survey Activities:":
            target_p = p
            target_p.paragraph_format.keep_with_next = True
            for r in target_p.runs:
                apply_font_and_format(r, is_bold=True, size_pt=11)
            break

    if not target_p:
        return

    days = parse_raw_daily_text(payload.get("raw_daily_text", ""))
    curr_p = target_p

    for day in days:
        p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=6, space_after_pt=2)
        run = p.add_run(day["date_full"])
        apply_font_and_format(run, is_bold=True, is_highlight=True, size_pt=10)
        curr_p = p

        for note in day.get("general_notes", []):
            p = insert_paragraph_after(curr_p, keep_with_next=False, space_before_pt=1, space_after_pt=1)
            run = p.add_run(f"- {note}" if not note.startswith("-") else note)
            apply_font_and_format(run, is_bold=False)
            curr_p = p

        if day["office_tasks"]:
            p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=2, space_after_pt=1)
            r1 = p.add_run("Wuqi Office: ")
            apply_font_and_format(r1, is_bold=True)
            r2 = p.add_run(day["office_staff"])
            apply_font_and_format(r2, is_bold=False)
            curr_p = p
            for t in day["office_tasks"]:
                p = insert_paragraph_after(curr_p, keep_with_next=False, space_before_pt=0, space_after_pt=1)
                run = p.add_run(f"- {t}")
                apply_font_and_format(run)
                curr_p = p

        if day["onshore_tasks"]:
            p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=2, space_after_pt=1)
            r1 = p.add_run("Onshore-Land: ")
            apply_font_and_format(r1, is_bold=True)
            r2 = p.add_run(day["onshore_staff"])
            apply_font_and_format(r2, is_bold=False)
            curr_p = p
            for t in day["onshore_tasks"]:
                p = insert_paragraph_after(curr_p, keep_with_next=False, space_before_pt=0, space_after_pt=1)
                run = p.add_run(f"- {t}")
                apply_font_and_format(run)
                curr_p = p

        if day["marine_tasks"]:
            p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=2, space_after_pt=1)
            r1 = p.add_run("Marine Offshore: ")
            apply_font_and_format(r1, is_bold=True)
            r2 = p.add_run(day["marine_staff"])
            apply_font_and_format(r2, is_bold=False)
            curr_p = p
            for t in day["marine_tasks"]:
                p = insert_paragraph_after(curr_p, keep_with_next=False, space_before_pt=0, space_after_pt=1)
                run = p.add_run(f"- {t}")
                apply_font_and_format(run)
                curr_p = p

        for v in day["vessels"]:
            p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=2, space_after_pt=1)
            r1 = p.add_run(v["header"])
            apply_font_and_format(r1, is_bold=True)
            curr_p = p

            p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=0, space_after_pt=1)
            r1 = p.add_run("Survey Boat: ")
            apply_font_and_format(r1, is_bold=True)
            r2 = p.add_run(v["boat"])
            apply_font_and_format(r2)
            curr_p = p

            p = insert_paragraph_after(curr_p, keep_with_next=True, space_before_pt=0, space_after_pt=1)
            r1 = p.add_run("Surveyor: ")
            apply_font_and_format(r1, is_bold=True)
            r2 = p.add_run(v["surveyor"])
            apply_font_and_format(r2)
            curr_p = p

            for st in v["statuses"]:
                p = insert_paragraph_after(curr_p, keep_with_next=False, space_before_pt=0, space_after_pt=1)
                run = p.add_run(f"- {st}")
                apply_font_and_format(run)
                curr_p = p


def insert_numbered_list(doc, heading_text: str, items: list):
    target_p = None
    for p in doc.paragraphs:
        if p.text.strip().lower() == heading_text.lower():
            target_p = p
            target_p.paragraph_format.keep_with_next = True
            target_p.paragraph_format.space_before = Pt(8)
            target_p.paragraph_format.space_after = Pt(2)
            for r in target_p.runs:
                apply_font_and_format(r, is_bold=True, size_pt=11)
            break

    if not target_p:
        return

    curr_p = target_p
    for idx, item in enumerate(items, 1):
        clean_item = re.sub(r"^\d+[\.\)]\s*", "", item.strip())
        if not clean_item:
            continue
        p = insert_paragraph_after(curr_p, keep_with_next=False, space_before_pt=1, space_after_pt=2)
        r_num = p.add_run(f"{idx}. ")
        apply_font_and_format(r_num, is_bold=True)
        r_txt = p.add_run(clean_item)
        apply_font_and_format(r_txt, is_bold=False)
        curr_p = p


def enforce_caption_and_heading_locks(doc):
    lock_prefixes = (
        "Personnel Overview",
        "Leave Planning",
        "Training and Pass Status",
        "Project Location",
        "ONSHORE",
        "Taichung AHDD Site:",
        "Taichung Tienli Site:",
        "Taichung Berth 37 Site:",
        "Tunghsiao Temporary Platform AHDD Site:",
        "NEARSHORE",
        "Trench 1",
        "Trench 8",
        "Midline Tie-In",
        "Dumping area monitoring",
        "– Monitoring Survey",
        "- Monitoring Survey",
        "OFFSHORE",
        "Pre Survey for Concrete Mattress",
        "Concrete Mattress Installation",
        "Pre-Survey on Pipeline Crossings",
        "Daily Survey Activities:",
        "Highlights",
        "Look ahead",
        "Outstanding Tasks",
        "Hardware Movement and Status",
        "NMDC Hardware from Abu Dhabi",
        "PDS Dongles",
        "NMDC Survey Vessel & Chartered Survey Vessel",
        "Dredging and Reclamation Overall Quantity",
        "Survey Document Summary",
        "Base Station and Tide Station:",
    )

    for p in doc.paragraphs:
        txt = p.text.strip()
        if not txt:
            continue
        if txt.startswith(lock_prefixes):
            p.paragraph_format.keep_with_next = True
            p.paragraph_format.keep_together = True
            p.paragraph_format.space_before = Pt(4)
            p.paragraph_format.space_after = Pt(2)
            for r in p.runs:
                r.font.name = "Arial"
                r.bold = True


def generate_wsr_documents(payload: dict) -> dict:
    from docxtpl import DocxTemplate, InlineImage

    admin_tables = payload.get("admin_tables")
    if admin_tables:
        save_admin_tables(admin_tables)
        try:
            tpl_doc = docx.Document(TEMPLATE_PATH)
            apply_admin_tables_to_doc(tpl_doc, admin_tables)
            tpl_doc.save(TEMPLATE_PATH)
        except Exception:
            pass

    tpl = DocxTemplate(TEMPLATE_PATH)
    context = {
        "year_week": payload.get("year_week", "2026.43"),
        "report_date_top": payload.get("report_date_top", "October 26, 2026"),
        "report_date_bottom": payload.get("report_date_bottom", "26th October 2026"),
    }

    category_widths = {
        "EXCEL_TABLE": 160,
        "ONSHORE": 150,
        "NEARSHORE": 122,
        "OFFSHORE": 118,
    }

    images_cfg = payload.get("images", {})
    for img_id, img_data in images_cfg.items():
        caption_key = f"date_{img_id}"
        context[caption_key] = img_data.get("new_date", "")

        b64_data = img_data.get("file_base64")
        if not img_data.get("keep_old", True) and b64_data:
            header, encoded = b64_data.split(",", 1) if "," in b64_data else ("", b64_data)
            ext = ".png" if "png" in header else ".jpg"
            for old_ext in [".png", ".jpg", ".jpeg"]:
                old_p = os.path.join(PERSISTENT_IMAGE_DIR, f"{img_id}{old_ext}")
                if os.path.exists(old_p):
                    os.remove(old_p)
            save_path = os.path.join(PERSISTENT_IMAGE_DIR, f"{img_id}{ext}")
            with open(save_path, "wb") as img_f:
                img_f.write(base64.b64decode(encoded))

        cat = img_data.get("category", "ONSHORE")
        width_mm = category_widths.get(cat, 130)
        if img_id == "img_tbl_doc_summary":
            width_mm = 148
        elif img_id == "img_tbl_hardware":
            width_mm = 152

        existing_img = find_persistent_image(img_id)
        if existing_img:
            context[img_id] = InlineImage(tpl, existing_img, width=Mm(width_mm))
        else:
            context[img_id] = f"[Missing Image: {img_id}]"

    for sec_photo in ["img_on_tienli_photo", "img_on_b37_photo", "img_on_tunghsiao_photo"]:
        sec_path = find_persistent_image(sec_photo)
        if sec_path:
            context[sec_photo] = InlineImage(tpl, sec_path, width=Mm(112))
        else:
            context[sec_photo] = ""

    week_str = context["year_week"]
    docx_name = f"20012-WSR-{week_str}.docx"
    pdf_name = f"20012-WSR-{week_str}.pdf"
    out_docx = os.path.join(OUTPUT_DIR, docx_name)
    out_pdf = os.path.join(OUTPUT_DIR, pdf_name)

    tpl.render(context)
    tpl.save(out_docx)

    doc = docx.Document(out_docx)
    if admin_tables:
        apply_admin_tables_to_doc(doc, admin_tables)
    insert_daily_logs(doc, payload)
    insert_numbered_list(doc, "Highlights", payload.get("highlights", []))
    insert_numbered_list(doc, "Look ahead", payload.get("look_ahead", []))
    insert_numbered_list(doc, "Outstanding Tasks", payload.get("outstanding_tasks", []))
    insert_numbered_list(doc, "Hardware Movement and Status", payload.get("hardware_status", []))
    enforce_caption_and_heading_locks(doc)
    doc.save(out_docx)

    pdf_created = False
    pdf_error = None

    if os.name == "nt" and docx2pdf_convert is not None:
        try:
            import pythoncom
            pythoncom.CoInitialize()
        except Exception:
            pass
        try:
            docx2pdf_convert(out_docx, out_pdf)
            pdf_created = os.path.exists(out_pdf)
        except Exception as e:
            pdf_error = str(e)
    else:
        # Linux / Render headless LibreOffice fallback if installed
        try:
            subprocess.run(
                ["soffice", "--headless", "--convert-to", "pdf", "--outdir", OUTPUT_DIR, out_docx],
                check=True, timeout=45, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
            )
            pdf_created = os.path.exists(out_pdf)
        except Exception as e:
            pdf_error = f"Word (.docx) generated; local MS Word / LibreOffice not present ({e})"

    return {
        "docx_filename": docx_name,
        "pdf_filename": pdf_name if pdf_created else None,
        "pdf_created": pdf_created,
        "pdf_error": pdf_error,
    }


