@wsr_bp.route("", methods=["GET"])
@wsr_bp.route("/", methods=["GET"])
def index():
    for candidate in [
        os.path.join(BASE_DIR, "NMDC_WSR_Portal_V13.html"),
        os.path.join(BASE_DIR, "templates", "NMDC_WSR_Portal_V13.html"),
    ]:
        if os.path.exists(candidate):
            return send_file(candidate)
    wildcard_matches = sorted(glob.glob(os.path.join(BASE_DIR, "*Portal*.html")), key=os.path.getmtime, reverse=True)
    if wildcard_matches:
        return send_file(wildcard_matches[0])
    auto_html_path = os.path.join(BASE_DIR, "NMDC_WSR_Portal_V13.html")
    try:
        with open(auto_html_path, "wb") as f:
            f.write(base64.b64decode(EMBEDDED_PORTAL_HTML_B64))
        return send_file(auto_html_path)
    except Exception:
        return base64.b64decode(EMBEDDED_PORTAL_HTML_B64).decode("utf-8", errors="ignore")


@wsr_bp.route("/api/admin_tables", methods=["GET", "POST"])
def api_admin_tables():
    if request.method == "POST":
        data = request.get_json(force=True)
        tables = data.get("admin_tables", data)
        save_admin_tables(tables)
        try:
            if os.path.exists(TEMPLATE_PATH):
                tpl_doc = docx.Document(TEMPLATE_PATH)
                apply_admin_tables_to_doc(tpl_doc, tables)
                tpl_doc.save(TEMPLATE_PATH)
        except Exception as e:
            return jsonify({"status": "error", "message": str(e)}), 200
        return jsonify({"status": "ok", "message": "Saved Page-1 Admin Tables to DPR Database & WSR_Master_Template_V8.docx!"})
    else:
        reload_from_tpl = request.args.get("reload") == "1"
        if reload_from_tpl:
            tables = extract_admin_tables_from_docx_file(TEMPLATE_PATH)
            if tables.get("personnel"):
                save_admin_tables(tables)
        else:
            tables = load_admin_tables()
        return jsonify({"status": "ok", "admin_tables": tables})


